process.env.WRANGLER_LOG = "debug";
function symptom(m) { console.error("FAIL: " + m); process.exit(1); }
function broken(m) { console.error("ERROR: " + m); process.exit(2); }
const w = require("wrangler");
const out = [];
const fmt = (x) => typeof x === "string" ? x : (x && x.stack) || JSON.stringify(x);
const real = { err: console.error, log: console.log };
for (const m of ["log", "error", "warn", "debug", "info"]) console[m] = (...a) => out.push(a.map(fmt).join(" "));
const D = w.unstable_DevEnv;
if (!D) broken("no unstable_DevEnv export");
const d = new D();
d.on("error", () => {});
const cause = new Error("Network connection lost.");
cause.stack = "Error: Network connection lost.\n    at fetch (ProxyWorker.ts:167:9)";
cause.cause = { name: "TypeError", message: "socket hang up" };
d.handleErrorEvent({ type: "error", source: "ProxyController", reason: "Error inside ProxyWorker", cause, data: {} });
const all = out.join("\n");
console.error = real.err; console.log = real.log;
if (!all.includes("Error inside ProxyWorker") || !all.includes("Network connection lost.")) broken("proxy error was not logged: " + all.slice(0, 300));
if (!all.includes("at fetch (ProxyWorker.ts:167:9)")) symptom("debug log of the failed proxied request has no error stack");
console.log("OK: debug log shows the stack of the failed proxied request");

